      const newStars = cung.stars.filter(s => s.name !== saoName);
      const hasChinhSao = newStars.some(s => s.type === 'chinh');
      
      return {
        ...cung,
        stars: newStars,
        isEmpty: !hasChinhSao,
        occupant: hasChinhSao 
